<?php
namespace App\Http\Controllers;use App\Jobs\ProcessMediaAsset;use App\Models\UploadBatch;use Illuminate\Http\Request;use Illuminate\Support\Facades\Gate;
class ProcessingController extends Controller {private function reply(Request$r,array$data){return$r->header('X-Inertia')?redirect()->back(303):response()->json($data);}private function allowed(UploadBatch $batch,Request $r):void{Gate::authorize('view',$batch->group);abort_unless($batch->user_id===$r->user()->id||$batch->group->creator_id===$r->user()->id,403);}public function show(Request $r,UploadBatch $batch){$this->allowed($batch,$r);return response()->json($batch->load('files:id,upload_batch_id,media_asset_id,client_filename,state,error,attempts'));}public function cancel(Request $r,UploadBatch $batch){$this->allowed($batch,$r);abort_if(in_array($batch->state,['completed','failed'],true),409);$batch->update(['state'=>'cancelled','cancelled_at'=>now()]);$batch->files()->whereIn('state',['pending','queued'])->update(['state'=>'cancelled']);return$this->reply($r,['state'=>'cancelled']);}public function retry(Request $r,UploadBatch $batch){$this->allowed($batch,$r);abort_if($batch->cancelled_at,409);foreach($batch->files()->where('state','failed')->whereNotNull('media_asset_id')->get()as$file){$file->update(['state'=>'queued','error'=>null]);ProcessMediaAsset::dispatch($file->media_asset_id,$file->id);} $batch->refreshCounts();return$this->reply($r,['state'=>$batch->fresh()->state]);}}
